const { verifyMetaWebhook } = require('/home/node/scripts/cvpro-helpers.js');
const query = $input.first().json.query || {};
const result = verifyMetaWebhook(query, process.env.WHATSAPP_WEBHOOK_VERIFY_TOKEN);
return [{ json: result }];

const body = $input.first().json.body;
const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];
if (!message) return [];
const from = message.from;
const msgType = message.type;
let text = '';
let mediaId = null;
let mimeType = '';
let caption = '';
if (msgType === 'text') {
  text = message.text?.body || '';
} else if (msgType === 'document') {
  mediaId = message.document?.id;
  mimeType = message.document?.mime_type;
  caption = message.document?.caption || '';
  text = caption;
} else if (msgType === 'image') {
  mediaId = message.image?.id;
  mimeType = message.image?.mime_type;
  caption = message.image?.caption || '';
  text = caption;
} else if (msgType === 'audio') {
  mediaId = message.audio?.id;
  mimeType = message.audio?.mime_type;
  text = '[voice_message]';
} else if (msgType === 'voice') {
  mediaId = message.voice?.id;
  mimeType = message.voice?.mime_type;
  text = '[voice_note]';
}
return [{
  json: {
    from,
    text,
    msgType,
    mediaId,
    mimeType,
    filename: message.document?.filename || 'uploaded_cv',
    phoneNumberId: value?.metadata?.phone_number_id,
    timestamp: message.timestamp,
    profileName: value?.contacts?.[0]?.profile?.name || ''
  }
}];

const input = $input.first().json;
const { getOrCreateCustomer, getOrCreateConversation, saveMessage } = require('/home/node/scripts/cvpro-helpers.js');

const customer = await getOrCreateCustomer($http, {
  phone_number: input.from,
  full_name: input.profileName,
});
const conversation = await getOrCreateConversation($http, customer.id, 'whatsapp');

if (input.msgType === 'text' && input.text) {
  await saveMessage($http, conversation.id, 'inbound', input.text, {
    content_type: 'text',
    is_ai_generated: false,
  });
}

return [{
  json: {
    ...input,
    customerId: customer.id,
    conversationId: conversation.id,
    humanTakeover: conversation.human_takeover,
  },
}];

const input = $input.first().json;
const MEDIA_TYPES = ['document', 'image', 'audio', 'voice'];
if (!MEDIA_TYPES.includes(input.msgType)) return [];

const token = process.env.WHATSAPP_ACCESS_TOKEN;
const mediaUrlResp = await $http.request({
  method: 'GET',
  url: `https://graph.facebook.com/v21.0/${input.mediaId}`,
  headers: { Authorization: `Bearer ${token}` },
});
const fileBuffer = await $http.request({
  method: 'GET',
  url: mediaUrlResp.url,
  encoding: 'arraybuffer',
});

return [{ json: { ...input, fileBuffer } }];

const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { saveMessage } = require('/home/node/scripts/cvpro-helpers.js');
const { fileBuffer, mimeType, msgType, conversationId } = $input.first().json;
const base64 = Buffer.from(fileBuffer).toString('base64');
const prompt = msgType === 'voice' || msgType === 'audio'
  ? 'Transcribe this audio message accurately. Return only the transcription text.'
  : 'Extract all text from this document/image. Return only the extracted text. If it is a CV or resume, note that.';

const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
const parts = [{ text: prompt }, { inlineData: { mimeType: mimeType || 'application/octet-stream', data: base64 } }];
let extractedText = '';
try {
  const res = await $http.request({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${process.env.GEMINI_API_KEYS.split(',')[0]}`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      contents: [{ parts }],
      generationConfig: { temperature: 0.2, maxOutputTokens: 2000 },
    },
  });
  extractedText = res.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch (_) {
  extractedText = await rotator.call(prompt, '', 2000, 0.2);
}

if (conversationId && extractedText) {
  const contentType = msgType === 'document' ? 'document' : msgType === 'image' ? 'image' : 'voice_note';
  await saveMessage($http, conversationId, 'inbound', extractedText, {
    content_type: contentType,
    is_ai_generated: false,
  });
}

return [{ json: { ...$input.first().json, extractedText, text: extractedText } }];

const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { saveCvAnalysis } = require('/home/node/scripts/cvpro-helpers.js');
const input = $input.first().json;
const text = input.text || input.extractedText;

if (!text || text.length < 50) {
  return [{ json: { ...input, skipCV: true } }];
}

const isLikelyCV = /CV|resume|خبرات|المهارات|experience|education/i.test(text) || text.length > 200;
if (!isLikelyCV) {
  return [{ json: { ...input, skipCV: true } }];
}

const systemPrompt = `You are an expert ATS and CV analyzer for the UAE/Gulf job market. Return JSON with: ats_score, formatting_score, keyword_score, readability_score, achievements_score, grammar_score, linkedin_compatibility_score, uae_gulf_score (all 0-100), weaknesses (array), improvement_suggestions (array), sales_pitch (Arabic), personalized_offer (object). Return ONLY valid JSON.`;

const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
let analysis = null;
try {
  analysis = await rotator.callJSON(text.substring(0, 6000), systemPrompt);
} catch (_) {
  return [{ json: { ...input, skipCV: true, cvError: true } }];
}

if (input.customerId) {
  await saveCvAnalysis($http, input.customerId, text, analysis, input.filename || 'uploaded_cv');
}

return [{ json: { ...input, cvAnalysis: analysis } }];

const {
  getMessageHistory,
  formatHistory,
  saveMessage,
  updateCustomer,
} = require('/home/node/scripts/cvpro-helpers.js');
const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { UpstashRedis } = require('/home/node/scripts/upstash-redis-adapter.js');

const input = $input.first().json;
const userText = input.text || input.extractedText || '';
const { from, customerId, conversationId, phoneNumberId, cvAnalysis, humanTakeover } = input;

if (humanTakeover) {
  return [{ json: { skipReply: true, from, phoneNumberId } }];
}

if (!userText.trim()) {
  return [{ json: { reply: 'شكراً لتواصلك! كيف يمكنني مساعدتك؟ 😊', from, phoneNumberId } }];
}

try {
  const redis = new UpstashRedis();
  const { allowed } = await redis.checkRateLimit(`ratelimit:wa:${from}`, 20, 60);
  if (!allowed) {
    return [{ json: { reply: 'يرجى الانتظار قليلاً ثم حاول مجدداً. 🙏', from, phoneNumberId } }];
  }
} catch (_) {}

const messages = await getMessageHistory($http, conversationId, 10);
const history = formatHistory(messages);

const cvContext = cvAnalysis
  ? `\nتحليل السيرة: نقاط الضعف: ${(cvAnalysis.weaknesses || []).join(', ')}. اقتراحات: ${(cvAnalysis.improvement_suggestions || cvAnalysis.improvements || []).join(', ')}.`
  : '';

const systemPrompt = `أنت وكيل مبيعات محترف لـ CVPro.ae (الإمارات والخليج).
الأسعار: Essential CV 399 | LinkedIn Pro 299 | Career Boost 599 | Executive 999 درهم.
ردود قصيرة (<200 كلمة). بالعربية أو الإنجليزية حسب العميل.
إذا طلب بشري، قل أنك ستحوله لخبير.
المحادثة:\n${history}${cvContext}`;

const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
let aiReply = '';
try {
  aiReply = await rotator.call(userText, systemPrompt, 350, 0.7);
} catch (_) {
  aiReply = 'شكراً لتواصلك مع CVPro.ae! كيف يمكنني مساعدتك اليوم؟ 😊';
}

await saveMessage($http, conversationId, 'outbound', aiReply, {
  is_ai_generated: true,
  ai_model: 'gemini-2.5-flash',
});

const needsHuman = /حولك|خبير|بشري|human/i.test(aiReply);
if (needsHuman) {
  await $http.request({
    method: 'PATCH',
    url: `${process.env.SUPABASE_URL}/rest/v1/conversations?id=eq.${conversationId}`,
    headers: {
      apikey: process.env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${process.env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Type': 'application/json',
    },
    body: { human_takeover: true, status: 'pending_human' },
  });
}

const patch = { last_interaction: new Date().toISOString() };
if (cvAnalysis) patch.lead_stage = 'analysis_done';
await updateCustomer($http, customerId, patch);

return [{ json: { reply: aiReply, from, phoneNumberId, customerId, conversationId, humanTakeover: needsHuman } }];
